// Section 24: single centralized loader for every presentation data file
// (spec items 45-47). Never hard-codes a benchmark number -- every value
// comes from presentation/public/data/*.json, generated by
// scripts/export_presentation_data.py from real, already-measured
// project artifacts. A file that is missing, unreadable, or `null`
// resolves to `null` here, never a fabricated fallback value -- callers
// render "Not available" / "Not measured" for a `null` field.

const DATA_FILES = [
  "benchmark_summary",
  "per_filter_results",
  "batch_sweep",
  "resolution_sweep",
  "correctness",
  "system",
  "threading",
  "optimization_results",
];

async function loadOne(name) {
  try {
    const res = await fetch(`${import.meta.env.BASE_URL}data/${name}.json`);
    if (!res.ok) return null;
    const data = await res.json();
    return data;
  } catch {
    return null;
  }
}

export async function loadPresentationData() {
  const entries = await Promise.all(DATA_FILES.map(async (name) => [name, await loadOne(name)]));
  return Object.fromEntries(entries);
}

export function isMissing(value) {
  return value === null || value === undefined;
}
